using AcxiomCrm.Data;using AcxiomCrm.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCrm.Controllers.Api;
[ApiController,Route("api/opportunities"),Authorize]public class OpportunitiesApiController:ControllerBase{private readonly ApplicationDbContext _db;public OpportunitiesApiController(ApplicationDbContext db)=>_db=db;[HttpGet]public async Task<IActionResult>Get()=>Ok(await _db.Opportunities.AsNoTracking().Select(x=>new{x.OpportunityId,x.OpportunityName,x.CustomerId,x.LeadId,x.Amount,x.Stage,x.Probability,x.ExpectedCloseDate,x.Status,x.AssignedTo,WeightedValue=x.Amount*x.Probability/100m}).ToListAsync());[HttpPost]public async Task<IActionResult>Post(Opportunity x){if(x.Amount<=0)ModelState.AddModelError(nameof(x.Amount),"Opportunity Amount must be greater than 0.");if(x.Probability<0||x.Probability>100)ModelState.AddModelError(nameof(x.Probability),"Probability must be between 0 and 100.");if(x.Status=="Open"&&x.ExpectedCloseDate.Date<DateTime.Today)ModelState.AddModelError(nameof(x.ExpectedCloseDate),"Expected Close Date cannot be in the past.");if(!ModelState.IsValid)return ValidationProblem(ModelState);_db.Add(x);await _db.SaveChangesAsync();return Created($"/api/opportunities/{x.OpportunityId}",new{x.OpportunityId,x.OpportunityName,x.Amount,x.Stage,x.Probability,x.ExpectedCloseDate,x.Status});}}
